# 1. Flink Job: IoT Data Pipeline with PII Masking, Aggregation, and S3 Sink

```java
package com.example.iot.pipeline;

import org.apache.flink.api.common.eventtime.*;
import org.apache.flink.api.common.functions.*;
import org.apache.flink.api.common.serialization.SimpleStringEncoder;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.common.typeinfo.TypeHint;
import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.metrics.Counter;
import org.apache.flink.metrics.Gauge;
import org.apache.flink.metrics.Histogram;
import org.apache.flink.metrics.Meter;
import org.apache.flink.metrics.MeterView;
import org.apache.flink.runtime.state.filesystem.FsStateBackend;
import org.apache.flink.shaded.jackson2.com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.flink.streaming.api.*;
import org.apache.flink.streaming.api.checkpointing.CheckpointingMode;
import org.apache.flink.streaming.api.datastream.*;
import org.apache.flink.streaming.api.environment.CheckpointConfig;
import org.apache.flink.streaming.api.functions.sink.filesystem.*;
import org.apache.flink.streaming.api.functions.sink.filesystem.bucketassigners.DateTimeBucketAssigner;
import org.apache.flink.streaming.api.functions.timestamps.*;
import org.apache.flink.streaming.api.windowing.assigners.TumblingEventTimeWindows;
import org.apache.flink.streaming.api.windowing.time.Time;

import java.time.Instant;
import java.util.*;

public class IoTDataPipeline {

    // POJO for input sensor event
    public static class SensorEvent {
        public String sensorId;
        public String eventId;
        public long timestamp; // event time in millis
        public String email;   // PII field
        public String phone;   // PII field
        public double temperature;
        public double humidity;

        // Default constructor needed for Flink POJO
        public SensorEvent() {}

        @Override
        public String toString() {
            return "SensorEvent{" +
                    "sensorId='" + sensorId + '\'' +
                    ", eventId='" + eventId + '\'' +
                    ", timestamp=" + timestamp +
                    ", email='" + email + '\'' +
                    ", phone='" + phone + '\'' +
                    ", temperature=" + temperature +
                    ", humidity=" + humidity +
                    '}';
        }
    }

    // POJO for aggregated output
    public static class SensorAggregate {
        public String sensorId;
        public long windowStart;
        public long windowEnd;
        public long eventCount;
        public double avgTemperature;
        public double avgHumidity;

        public SensorAggregate() {}

        @Override
        public String toString() {
            return "SensorAggregate{" +
                    "sensorId='" + sensorId + '\'' +
                    ", windowStart=" + Instant.ofEpochMilli(windowStart) +
                    ", windowEnd=" + Instant.ofEpochMilli(windowEnd) +
                    ", eventCount=" + eventCount +
                    ", avgTemperature=" + avgTemperature +
                    ", avgHumidity=" + avgHumidity +
                    '}';
        }
    }

    // PII Masking Function
    public static class PIIMaskingMapFunction extends RichMapFunction<SensorEvent, SensorEvent> {

        private transient Counter maskedEmailCounter;
        private transient Counter maskedPhoneCounter;

        @Override
        public void open(Configuration parameters) {
            maskedEmailCounter = getRuntimeContext()
                    .getMetricGroup()
                    .counter("maskedEmailCount");
            maskedPhoneCounter = getRuntimeContext()
                    .getMetricGroup()
                    .counter("maskedPhoneCount");
        }

        @Override
        public SensorEvent map(SensorEvent event) throws Exception {
            if (event.email != null && !event.email.isEmpty()) {
                event.email = maskEmail(event.email);
                maskedEmailCounter.inc();
            }
            if (event.phone != null && !event.phone.isEmpty()) {
                event.phone = maskPhone(event.phone);
                maskedPhoneCounter.inc();
            }
            return event;
        }

        private String maskEmail(String email) {
            // Simple mask: replace local part with xxxx
            int atIdx = email.indexOf('@');
            if (atIdx > 1) {
                return "xxxx" + email.substring(atIdx);
            }
            return "xxxx@masked.com";
        }

        private String maskPhone(String phone) {
            // Mask all but last 4 digits
            if (phone.length() > 4) {
                int maskLen = phone.length() - 4;
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < maskLen; i++) {
                    sb.append('X');
                }
                sb.append(phone.substring(maskLen));
                return sb.toString();
            }
            return "XXXX";
        }
    }

    // Aggregation function to compute averages and counts
    public static class AggregateFunction
            implements AggregateFunction<SensorEvent, Tuple4<Long, Double, Double, Long>, SensorAggregate> {

        // Accumulator: (count, sumTemp, sumHumidity, windowEndTimestamp)
        @Override
        public Tuple4<Long, Double, Double, Long> createAccumulator() {
            return Tuple4.of(0L, 0.0, 0.0, 0L);
        }

        @Override
        public Tuple4<Long, Double, Double, Long> add(SensorEvent value, Tuple4<Long, Double, Double, Long> accumulator) {
            return Tuple4.of(
                    accumulator.f0 + 1,
                    accumulator.f1 + value.temperature,
                    accumulator.f2 + value.humidity,
                    accumulator.f3
            );
        }

        @Override
        public SensorAggregate getResult(Tuple4<Long, Double, Double, Long> accumulator) {
            SensorAggregate agg = new SensorAggregate();
            agg.eventCount = accumulator.f0;
            if (accumulator.f0 > 0) {
                agg.avgTemperature = accumulator.f1 / accumulator.f0;
                agg.avgHumidity = accumulator.f2 / accumulator.f0;
            } else {
                agg.avgTemperature = 0.0;
                agg.avgHumidity = 0.0;
            }
            agg.windowEnd = accumulator.f3;
            return agg;
        }

        @Override
        public Tuple4<Long, Double, Double, Long> merge(Tuple4<Long, Double, Double, Long> a, Tuple4<Long, Double, Double, Long> b) {
            return Tuple4.of(
                    a.f0 + b.f0,
                    a.f1 + b.f1,
                    a.f2 + b.f2,
                    Math.max(a.f3, b.f3)
            );
        }
    }

    // ProcessWindowFunction to add sensorId and window bounds
    public static class WindowResultFunction extends ProcessWindowFunction<SensorAggregate, SensorAggregate, String, TimeWindow> {
        @Override
        public void process(String sensorId, Context context, Iterable<SensorAggregate> elements, Collector<SensorAggregate> out) {
            SensorAggregate agg = elements.iterator().next();
            agg.sensorId = sensorId;
            agg.windowStart = context.window().getStart();
            agg.windowEnd = context.window().getEnd();
            out.collect(agg);
        }
    }

    public static void main(String[] args) throws Exception {
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Checkpoint config for exactly-once and 500ms interval
        env.enableCheckpointing(500);
        env.getCheckpointConfig().setCheckpointingMode(CheckpointingMode.EXACTLY_ONCE);
        env.getCheckpointConfig().setMinPauseBetweenCheckpoints(250);
        env.getCheckpointConfig().setCheckpointTimeout(60000);
        env.getCheckpointConfig().enableExternalizedCheckpoints(CheckpointConfig.ExternalizedCheckpointCleanup.RETAIN_ON_CANCELLATION);

        // Recommended state backend - can be configured for production
        env.setStateBackend(new FsStateBackend("s3://your-flink-checkpoints-bucket/checkpoints"));

        // Set parallelism >= 20 as per design
        env.setParallelism(20);

        // Source: Kafka consumer (assumed configured externally)
        // For demo, we will simulate a source (replace with Kafka consumer in production)
        DataStream<String> rawJsonStream = env.addSource(new SimulatedSensorSource());

        // Deserialize JSON to SensorEvent POJO
        DataStream<SensorEvent> events = rawJsonStream
                .map(json -> {
                    ObjectMapper mapper = new ObjectMapper();
                    return mapper.readValue(json, SensorEvent.class);
                })
                .returns(TypeInformation.of(SensorEvent.class))
                // Assign timestamps and watermarks for event-time processing
                .assignTimestampsAndWater

