                .assignTimestampsAndWatermarks(
                    WatermarkStrategy.<SensorEvent>forBoundedOutOfOrderness(Duration.ofSeconds(1))
                        .withTimestampAssigner((event, timestamp) -> event.timestamp)
                );

        // Apply PII masking
        DataStream<SensorEvent> maskedEvents = events
                .map(new PIIMaskingMapFunction());

        // Key by sensorId for per-sensor aggregation
        KeyedStream<SensorEvent, String> keyed = maskedEvents
                .keyBy(event -> event.sensorId);

        // Aggregate with 1-second tumbling windows
        SingleOutputStreamOperator<SensorAggregate> aggregates = keyed
                .window(TumblingEventTimeWindows.of(Time.seconds(1)))
                .aggregate(
                        new AggregateFunction(),
