        // Sink to S3 with SSE-KMS encryption enabled
        // Using Flink Streaming File Sink (bucketized by event date)
        StreamingFileSink<String> s3Sink = StreamingFileSink
                .forRowFormat(new Path("s3a://your-bucket/iot/aggregates/"),
                        new SimpleStringEncoder<String>("UTF-8"))
                .withBucketAssigner(new DateTimeBucketAssigner<>("yyyy-MM-dd"))
                .withRollingPolicy(DefaultRollingPolicy.builder()
                        .withRolloverInterval(TimeUnit.MINUTES.toMillis(15))
                        .withInactivityInterval(TimeUnit.MINUTES.toMillis(5))
                        .withMaxPartSize(1024 * 1024 * 128) // 128MB
                        .build())
                .build();

        aggregatesJson.addSink(s3Sink);

        // TODO: Add Prometheus metrics integration (counters, gauges for latency, throughput, errors)
        // This can be done by implementing custom MetricReporter or using existing Flink PrometheusReporter

        env.execute("IoT Data Pipeline with PII Masking and Aggregation");
