    // Simulated source for testing, replace with real KafkaConsumer in prod
    public static class SimulatedSensorSource implements SourceFunction<String> {
        private volatile boolean running = true;
        private Random rand = new Random();

        @Override
        public void run(SourceContext<String> ctx) throws Exception {
            ObjectMapper mapper = new ObjectMapper();
            while (running) {
                SensorEvent event = new SensorEvent();
                event.sensorId = "sensor-" + (rand.nextInt(10000) + 1);
                event.eventId = UUID.randomUUID().toString();
                event.timestamp = System.currentTimeMillis() - rand.nextInt(1000);
                event.email = "user" + rand.nextInt(1000) + "@example.com";
                event.phone = "5551234" + (rand.nextInt(9000) + 1000);
                event.temperature = 20 + rand.nextDouble() * 10;
                event.humidity = 40 + rand.nextDouble() * 20;

                String json = mapper.writeValueAsString(event);
                synchronized (ctx.getCheckpointLock()) {
                    ctx.collect(json);
                }
                Thread.sleep(10); // simulate ~100 events/sec
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }
}
