# 1. Flink Job (Java) — Full Source with Modular PII Masking & Checkpointing

```java
package com.example.iot;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.AggregateFunction;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.common.serialization.SimpleStringEncoder;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.core.fs.Path;
import org.apache.flink.metrics.Counter;
import org.apache.flink.metrics.Gauge;
import org.apache.flink.streaming.api.CheckpointingMode;
import org.apache.flink.streaming.api.TimeCharacteristic;
import org.apache.flink.streaming.api.datastream.*;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.sink.filesystem.StreamingFileSink;
import org.apache.flink.streaming.api.functions.sink.filesystem.bucketassigners.DateTimeBucketAssigner;
import org.apache.flink.streaming.api.windowing.assigners.TumblingEventTimeWindows;
import org.apache.flink.streaming.api.windowing.time.Time;

import java.io.IOException;
import java.time.Duration;
import java.util.UUID;
import java.util.concurrent.TimeUnit;

// SensorEvent POJO
public class SensorEvent {
    public String sensorId;
    public String eventId;
    public long timestamp; // epoch millis
    public String email;
    public String phone;
    public double temperature;
    public double humidity;

    // Default constructor needed by Flink
    public SensorEvent() {}

    // Copy constructor or builder can be added if needed
}

// Aggregated result POJO
public class SensorAggregate {
    public String sensorId;
    public long windowStart;
    public long windowEnd;
    public double avgTemperature;
    public double avgHumidity;
    public long eventCount;

    public SensorAggregate() {}

    public SensorAggregate(String sensorId, long windowStart, long windowEnd,
                           double avgTemperature, double avgHumidity, long eventCount) {
        this.sensorId = sensorId;
        this.windowStart = windowStart;
        this.windowEnd = windowEnd;
        this.avgTemperature = avgTemperature;
        this.avgHumidity = avgHumidity;
        this.eventCount = eventCount;
    }
}

// Modular PII Masking MapFunction
public class PIIMaskingMapFunction implements MapFunction<SensorEvent, SensorEvent> {

    private transient Counter maskedEmailCounter;
    private transient Counter maskedPhoneCounter;

    @Override
    public SensorEvent map(SensorEvent event) throws Exception {
        // Mask email and phone (simple example: redact completely)
        if (event.email != null && !event.email.isEmpty()) {
            event.email = maskEmail(event.email);
            if (maskedEmailCounter != null) maskedEmailCounter.inc();
        }
        if (event.phone != null && !event.phone.isEmpty()) {
            event.phone = maskPhone(event.phone);
            if (maskedPhoneCounter != null) maskedPhoneCounter.inc();
        }
        return event;
    }

    private String maskEmail(String email) {
        // Replace local part with asterisks
        int atIndex = email.indexOf('@');
        if (atIndex > 0) {
            return "*****" + email.substring(atIndex);
        }
        return "*****";
    }

    private String maskPhone(String phone) {
        // Mask all digits except last 2
        if (phone.length() > 2) {
            return "******" + phone.substring(phone.length() - 2);
        }
        return "******";
    }

    @Override
    public void open(Configuration parameters) {
        maskedEmailCounter = getRuntimeContext()
            .getMetricGroup()
            .counter("maskedEmailCount");
        maskedPhoneCounter = getRuntimeContext()
            .getMetricGroup()
            .counter("maskedPhoneCount");
    }
}

// AggregateFunction to compute averages and counts
public class SensorAggregateFunction implements AggregateFunction<SensorEvent, AggregateAccumulator, SensorAggregate> {

    @Override
    public AggregateAccumulator createAccumulator() {
        return new AggregateAccumulator();
    }

    @Override
