            if (event.email != null && !event.email.isEmpty()) {
                event.email = maskEmail(event.email);
                maskedEmailCounter.inc();
            }
            if (event.phone != null && !event.phone.isEmpty()) {
                event.phone = maskPhone(event.phone);
                maskedPhoneCounter.inc();
            }
            return event;
        }

