    // PII Masking Function
    public static class PIIMaskingMapFunction extends RichMapFunction<SensorEvent, SensorEvent> {

        private transient Counter maskedEmailCounter;
        private transient Counter maskedPhoneCounter;

        @Override
        public void open(Configuration parameters) {
            maskedEmailCounter = getRuntimeContext()
                    .getMetricGroup()
                    .counter("maskedEmailCount");
            maskedPhoneCounter = getRuntimeContext()
                    .getMetricGroup()
                    .counter("maskedPhoneCount");
        }

        @Override
        public SensorEvent map(SensorEvent event) throws Exception {
            if (event.email != null && !event.email.isEmpty()) {
                event.email = maskEmail(event.email);
                maskedEmailCounter.inc();
            }
            if (event.phone != null && !event.phone.isEmpty()) {
                event.phone = maskPhone(event.phone);
                maskedPhoneCounter.inc();
            }
            return event;
        }

        private String maskEmail(String email) {
            // Simple mask: replace local part with xxxx
            int atIdx = email.indexOf('@');
            if (atIdx > 1) {
                return "xxxx" + email.substring(atIdx);
            }
            return "xxxx@masked.com";
        }

        private String maskPhone(String phone) {
            // Mask all but last 4 digits
            if (phone.length() > 4) {
                int maskLen = phone.length() - 4;
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < maskLen; i++) {
                    sb.append('X');
                }
                sb.append(phone.substring(maskLen));
                return sb.toString();
            }
            return "XXXX";
        }
    }

    // Aggregation function to compute averages and counts
    public static class AggregateFunction
            implements AggregateFunction<SensorEvent, Tuple4<Long, Double, Double, Long>, SensorAggregate> {

        // Accumulator: (count, sumTemp, sumHumidity, windowEndTimestamp)
        @Override
        public Tuple4<Long, Double, Double, Long> createAccumulator() {
            return Tuple4.of(0L, 0.0, 0.0, 0L);
        }

        @Override
        public Tuple4<Long, Double, Double, Long> add(SensorEvent value, Tuple4<Long, Double, Double, Long> accumulator) {
            return Tuple4.of(
                    accumulator.f0 + 1,
                    accumulator.f1 + value.temperature,
                    accumulator.f2 + value.humidity,
                    accumulator.f3
            );
        }

        @Override
        public SensorAggregate getResult(Tuple4<Long, Double, Double, Long> accumulator) {
            SensorAggregate agg = new SensorAggregate();
            agg.eventCount = accumulator.f0;
            if (accumulator.f0 > 0) {
                agg.avgTemperature = accumulator.f1 / accumulator.f0;
                agg.avgHumidity = accumulator.f2 / accumulator.f0;
            } else {
                agg.avgTemperature = 0.0;
                agg.avgHumidity = 0.0;
            }
            agg.windowEnd = accumulator.f3;
            return agg;
        }

        @Override
        public Tuple4<Long, Double, Double, Long> merge(Tuple4<Long, Double, Double, Long> a, Tuple4<Long, Double, Double, Long> b) {
            return Tuple4.of(
                    a.f0 + b.f0,
                    a.f1 + b.f1,
                    a.f2 + b.f2,
                    Math.max(a.f3, b.f3)
            );
        }
    }

    // ProcessWindowFunction to add sensorId and window bounds
    public static class WindowResultFunction extends ProcessWindowFunction<SensorAggregate, SensorAggregate, String, TimeWindow> {
        @Override
        public void process(String sensorId, Context context, Iterable<SensorAggregate> elements, Collector<SensorAggregate> out) {
            SensorAggregate agg = elements.iterator().next();
            agg.sensorId = sensorId;
            agg.windowStart = context.window().getStart();
            agg.windowEnd = context.window().getEnd();
            out.collect(agg);
        }
    }

