# Kafka Producer Prototype (Python)

Here is a Python Kafka producer snippet using `confluent-kafka` that:

- Sends JSON messages with PII fields

- Uses lz4 compression, linger.ms=5ms, batch.size=32KB

- Simulates steady and burst load patterns for 10k sensors

```python
from confluent_kafka import Producer
import json
import time
import random
import uuid
import threading

# Kafka configuration
conf = {
    'bootstrap.servers': 'your.kafka.broker:9092',
    'compression.type': 'lz4',
    'linger.ms': 5,
    'batch.size': 32768,  # 32KB
    'acks': 'all',
    'enable.idempotence': True,
}

producer = Producer(conf)
topic = 'sensor-events'

NUM_SENSORS = 10000

def generate_event(sensor_id):
    event = {
        "sensorId": f"sensor-{sensor_id}",
        "eventId": str(uuid.uuid4()),
        "timestamp": int(time.time() * 1000),
        "email": f"user{sensor_id}@example.com",
        "phone": f"5551234{random.randint(1000,9999)}",
        "temperature": round(20 + random.random()*10, 2),
        "humidity": round(40 + random.random()*20, 2)
    }
    return event

def delivery_report(err, msg):
    if err is not None:
        print(f"Delivery failed for record {msg.key()}: {err}")

def produce_steady_rate(rate_per_sec=1000):
    interval = 1.0 / rate_per_sec
    sensor_ids = list(range(1, NUM_SENSORS+1))
    while True:
        sensor_id = random.choice(sensor_ids)
        event = generate_event(sensor_id)
        producer.produce(topic, json.dumps(event).encode('utf-8'), callback=delivery_report)
        producer.poll(0)
        time.sleep(interval)

def produce_burst(burst_size=5000, burst_duration_sec=1):
    sensor_ids = list(range(1, NUM_SENSORS+1))
    start_time = time.time()
    sent = 0
    while time.time() - start_time < burst_duration_sec and sent < burst_size:
        sensor_id = random.choice(sensor_ids)
        event = generate_event(sensor_id)
        producer.produce(topic, json.dumps(event).encode('utf-8'), callback=delivery_report)
        producer.poll(0)
        sent += 1
    producer.flush()

if __name__ == '__main__':
    # Example: Run steady producer in background
    steady_thread = threading.Thread(target=produce_steady_rate, args=(500,))
    steady_thread.daemon = True
    steady_thread.start()

    # Simulate burst every 30 seconds
    while True:
        time.sleep(30)
        print("Starting burst load")
        produce_burst(burst_size=20000, burst_duration_sec=2)
        print("Burst load finished")
```

