// Modular PII Masking MapFunction
public class PIIMaskingMapFunction implements MapFunction<SensorEvent, SensorEvent> {

    private transient Counter maskedEmailCounter;
    private transient Counter maskedPhoneCounter;

    @Override
    public SensorEvent map(SensorEvent event) throws Exception {
        // Mask email and phone (simple example: redact completely)
        if (event.email != null && !event.email.isEmpty()) {
            event.email = maskEmail(event.email);
            if (maskedEmailCounter != null) maskedEmailCounter.inc();
        }
        if (event.phone != null && !event.phone.isEmpty()) {
            event.phone = maskPhone(event.phone);
            if (maskedPhoneCounter != null) maskedPhoneCounter.inc();
        }
        return event;
    }

    private String maskEmail(String email) {
        // Replace local part with asterisks
        int atIndex = email.indexOf('@');
        if (atIndex > 0) {
            return "*****" + email.substring(atIndex);
        }
        return "*****";
    }

    private String maskPhone(String phone) {
        // Mask all digits except last 2
        if (phone.length() > 2) {
            return "******" + phone.substring(phone.length() - 2);
        }
        return "******";
    }

    @Override
    public void open(Configuration parameters) {
        maskedEmailCounter = getRuntimeContext()
            .getMetricGroup()
            .counter("maskedEmailCount");
        maskedPhoneCounter = getRuntimeContext()
            .getMetricGroup()
            .counter("maskedPhoneCount");
    }
}

// AggregateFunction to compute averages and counts
public class SensorAggregateFunction implements AggregateFunction<SensorEvent, AggregateAccumulator, SensorAggregate> {

    @Override
    public AggregateAccumulator createAccumulator() {
        return new AggregateAccumulator();
    }

    @Override
    public AggregateAccumulator add(SensorEvent value, AggregateAccumulator accumulator) {
        accumulator.sumTemperature += value.temperature;
        accumulator.sumHumidity += value.humidity;
        accumulator.count += 1;
        return accumulator;
    }

    @Override
    public SensorAggregate getResult(AggregateAccumulator accumulator) {
        return new SensorAggregate(
                accumulator.sensorId,
                accumulator.windowStart,
                accumulator.windowEnd,
                accumulator.count == 0 ? 0 : accumulator.sumTemperature / accumulator.count,
                accumulator.count == 0 ? 0 : accumulator.sumHumidity / accumulator.count,
                accumulator.count
        );
    }

    @Override
    public AggregateAccumulator merge(AggregateAccumulator a, AggregateAccumulator b) {
        a.sumTemperature += b.sumTemperature;
        a.sumHumidity += b.sumHumidity;
        a.count += b.count;
        return a;
    }
}

