            .getMetricGroup()
            .counter("maskedEmailCount");
        maskedPhoneCounter = getRuntimeContext()
            .getMetricGroup()
            .counter("maskedPhoneCount");
    }
}

// AggregateFunction to compute averages and counts
public class SensorAggregateFunction implements AggregateFunction<SensorEvent, AggregateAccumulator, SensorAggregate> {

    @Override
    public AggregateAccumulator createAccumulator() {
        return new AggregateAccumulator();
    }

    @Override
    public AggregateAccumulator add(SensorEvent value, AggregateAccumulator accumulator) {
        accumulator.sumTemperature += value.temperature;
        accumulator.sumHumidity += value.humidity;
        accumulator.count += 1;
        return accumulator;
    }

    @Override
    public SensorAggregate getResult(AggregateAccumulator accumulator) {
        return new SensorAggregate(
                accumulator.sensorId,
                accumulator.windowStart,
                accumulator.windowEnd,
                accumulator.count == 0 ? 0 : accumulator.sumTemperature / accumulator.count,
                accumulator.count == 0 ? 0 : accumulator.sumHumidity / accumulator.count,
                accumulator.count
        );
    }

    @Override
    public AggregateAccumulator merge(AggregateAccumulator a, AggregateAccumulator b) {
        a.sumTemperature += b.sumTemperature;
        a.sumHumidity += b.sumHumidity;
        a.count += b.count;
        return a;
    }
}

// Helper accumulator class
public class AggregateAccumulator {
    public String sensorId;
    public long windowStart = -1L;
    public long windowEnd = -1L;
    public double sumTemperature = 0.0;
    public double sumHumidity = 0.0;
    public long count = 0;

    public AggregateAccumulator() {}
}

// Window function to add window metadata to accumulator
import org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction;
import org.apache.flink.util.Collector;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;

public class WindowResultFunction extends ProcessWindowFunction<SensorAggregate, SensorAggregate, String, TimeWindow> {
    @Override
    public void process(String key, Context context, Iterable<SensorAggregate> elements, Collector<SensorAggregate> out) {
        SensorAggregate agg = elements.iterator().next();
        agg.sensorId = key;
        agg.windowStart = context.window().getStart();
        agg.windowEnd = context.window().getEnd();
        out.collect(agg);
    }
}

public class IoTDataPipelineJob {
    public static void main(String[] args) throws Exception {
        final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Enable event time
        env.setStreamTimeCharacteristic(TimeCharacteristic.EventTime);
        env.enableCheckpointing(500); // 500ms checkpoint interval
        env.getCheckpointConfig().setCheckpointingMode(CheckpointingMode.EXACTLY_ONCE);
        env.getCheckpointConfig().setMinPauseBetweenCheckpoints(200);
        env.getCheckpointConfig().setCheckpointTimeout(60000);
        env.getCheckpointConfig().enableExternalizedCheckpoints(
                org.apache.flink.streaming.api.CheckpointConfig.ExternalizedCheckpointCleanup.RETAIN_ON_CANCELLATION);

        // Configure state backend to S3 with SSE-KMS (configured externally)
        // Example (depends on your Flink distribution):
        // env.setStateBackend(new FsStateBackend("s3a://your-bucket/flink-checkpoints/"));

        // Source: Replace SimulatedSensorSource with KafkaConsumer configured with low-latency and lz4 compression
        DataStream<String> sourceStream = env.addSource(new SimulatedSensorSource());

        ObjectMapper mapper = new ObjectMapper();

        DataStream<SensorEvent> events = sourceStream
                .map(json -> mapper.readValue(json, SensorEvent.class))
                .returns(SensorEvent.class)
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<SensorEvent>forBoundedOutOfOrderness(Duration.ofSeconds(1))
                                .withTimestampAssigner((event, ts) -> event.timestamp)
                );

        DataStream<SensorEvent> maskedEvents = events.map(new PIIMaskingMapFunction());

        KeyedStream<SensorEvent, String> keyed = maskedEvents.keyBy(event -> event.sensorId);

        SingleOutputStreamOperator<SensorAggregate> aggregates = keyed
                .window(TumblingEventTimeWindows.of(Time.seconds(1)))
                .aggregate(new SensorAggregateFunction(), new WindowResultFunction());

        DataStream<String> aggregatesJson = aggregates.map(agg -> mapper.writeValueAsString(agg));

        StreamingFileSink<String> s3Sink = StreamingFileSink
                .forRowFormat(new Path("s3a://your-bucket/iot/aggregates/"), new SimpleStringEncoder<String>("UTF-8"))
                .withBucketAssigner(new DateTimeBucketAssigner<>("yyyy-MM-dd"))
                .withRollingPolicy(
                        DefaultRollingPolicy.builder()
                                .withRolloverInterval(TimeUnit.MINUTES.toMillis(15))
                                .withInactivityInterval(TimeUnit.MINUTES.toMillis(5))
                                .withMaxPartSize(128 * 1024 * 1024)
                                .build())
                .build();

        aggregatesJson.addSink(s3Sink);

        // TODO: Add PrometheusReporter config in flink-conf.yaml and/or code hooks for latency, throughput, errors

        env.execute("IoT Data Pipeline with PII Masking and Aggregation");
    }

